import{_ as s,c as t,o as l,j as e,a as n}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"乾下兌上 夬：","description":"京氏易傳 - 乾下兌上 夬：","frontmatter":{"title":"乾下兌上 夬：","description":"京氏易傳 - 乾下兌上 夬："},"headers":[],"relativePath":"classics/jingshi/039.md","filePath":"classics/jingshi/039.md"}'),i={name:"classics/jingshi/039.md"};function r(c,a,o,p,d,u){return l(),t("div",null,[...a[0]||(a[0]=[e("h1",{id:"乾下兌上-夬",tabindex:"-1"},[n("乾下兌上 夬： "),e("a",{class:"header-anchor",href:"#乾下兌上-夬","aria-label":"Permalink to “乾下兌上 夬：”"},"​")],-1),e("p",null,"剛決柔，陰道滅。五陽務下，一陰危上，將反遊魂。九四，悔也。",-1),e("p",null,"澤上於天，君道行也。【夬，五世。六位週而復始，為遊魂。至九四成陰，入坎為需。】與兌為飛伏。【丁酉金，癸亥水。】九五立世，九二大夫為應。【九五在兌象為世，澤小於天也。】",-1),e("p",null,"建始己亥至甲辰，【小雪，清明。】積算起甲辰至癸卯，週而復始。金木分乾兌入坤象。【入坤宮起積算。】",-1),e("p",null,"五星從位起太陰，【太陰，水星。入卦起算。】亢宿從位降丁酉，【二十八宿配亢宿，入夬卦丁酉金上起。】分氣候二十八。【積算起宮二十八，入卦中甲辰，還丁酉金上定吉凶。】",-1),e("p",null,"《易》雲：“澤上於天，夬”。“揚於王庭”。柔道消，消不可極，反於遊魂。九四柔來文剛，陰道存也，陰之道不可終否。剛柔相濟，日月明矣；天地定位，人事通也。【凡卦，陰極陽生，陽極陰生，生生之義，不絕之貌。日月循環，天地交泰，陰陽相蕩，六位交分，萬物生焉。】故曰：雷動風行，山澤通氣。人之運動，體斯合矣。【人稟五常，三焦九竅，風火逓（遞）相兼濟，以一位虧，四體羸焉。】",-1),e("p",null,"陰陽升降，反覆道也。次降入遊魂水天需卦。",-1)])])}const f=s(i,[["render",r]]);export{_ as __pageData,f as default};
